// === Tab: mySketch.js ===
let particles = [];
let numParticles = 500;
let noiseScale = 0.01;
let hueOffset = 0;
let speedMultiplier = 3;

function setup() {
  createCanvas(windowWidth, windowWidth*.75);
  colorMode(HSB, 360, 100, 100, 100);
  noFill();
  background(0);

  for (let i = 0; i < numParticles; i++) {
    particles.push(createVector(random(width), random(height)));
  }
}

function draw() {
  strokeWeight(1);
	if (frameCount%10000 == 0)  saveCanvas("spiralFlowArt", "jpg");
  for (let i = 0; i < particles.length; i++) {
    let p = particles[i];
    let angle = noise(p.x * noiseScale, p.y * noiseScale, frameCount * 0.002) * TWO_PI * 4;
    let v = p5.Vector.fromAngle(angle).mult(speedMultiplier);
    p.add(v);

    stroke((angle * 30 + hueOffset) % 360, 80, 100, 10);
    point(p.x, p.y);

    if (p.x < 0 || p.x > width || p.y < 0 || p.y > height) {
      p.x = random(width);
      p.y = random(height);
    }
  }

  hueOffset += 0.2;
}

function keyPressed() {
  saveCanvas("spiralFlowArt", "jpg");
}

setTimeout(() => {
	saveCanvas("spiralFlowArt", "jpg");
  window.location.reload();
}, 3 * 60 * 1000);

